/**
 * Determines if a polygon defined by its vertices is convex
 * @param {Array<{x: number, y: number}>} points - Array of point objects representing polygon vertices in order
 * @returns {boolean} True if the polygon is convex, false otherwise
 */
function isConvex(points) {
    // Validate input
    if (!Array.isArray(points)) {
        throw new Error("isConvex: points must be an array");
    }
    if (points.length < 3) {
        throw new Error("isConvex: a polygon must have at least 3 vertices");
    }

    for (let i = 0; i < points.length; i++) {
        const point = points[i];
        if (!point || typeof point !== 'object' || point.x === undefined || point.y === undefined) {
            throw new Error(`isConvex: point at index ${i} must be an object with x and y properties`);
        }
        if (typeof point.x !== 'number' || !isFinite(point.x)) {
            throw new Error(`isConvex: point at index ${i} has invalid x coordinate: ${point.x}`);
        }
        if (typeof point.y !== 'number' || !isFinite(point.y)) {
            throw new Error(`isConvex: point at index ${i} has invalid y coordinate: ${point.y}`);
        }
    }

    // For a convex polygon, all cross products of consecutive triplets of vertices
    // should have the same sign (all positive or all negative)
    let prevCrossProduct = 0;
    const n = points.length;

    for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;
        const k = (i + 2) % n;

        const cross = crossProduct(points[i], points[j], points[k]);

        // If this is the first cross product, set it as reference
        if (i === 0) {
            prevCrossProduct = cross;
        } else {
            // If cross product is zero, the points are collinear - not strictly convex
            if (cross === 0) {
                return false;
            }

            // If signs differ, not convex
            if ((cross > 0) !== (prevCrossProduct > 0)) {
                return false;
            }
        }
    }

    return true;
}

// Export functions for use in other modules
module.exports = {
    distance,
    polygonArea,
    perimeter,
    centroid,
    boundingBox,
    pointInPolygon,
    convexHull,
    isConvex,
    translate,
    scale
};

// test_convex_hull.js - Test the isConvex function

const { isConvex } = require('./r4_geom.js');

// Test cases
console.log("Testing isConvex function...\n");

// Test 1: Square (convex)
const square = [
    {x: 0, y: 0},
    {x: 1, y: 0},
    {x: 1, y: 1},
    {x: 0, y: 1}
];
console.log("Square (convex):", isConvex(square));

// Test 2: Triangle (convex)
const triangle = [
    {x: 0, y: 0},
    {x: 1, y: 0},
    {x: 0.5, y: 1}
];
console.log("Triangle (convex):", isConvex(triangle));

// Test 3: Star shape (non-convex)
const star = [
    {x: 0, y: 0},
    {x: 1, y: 0},
    {x: 0.5, y: 1},
    {x: 0, y: 0.5},
    {x: 1, y: 0.5}
];
console.log("Star shape (non-convex):", isConvex(star));

// Test 4: Concave quadrilateral (non-convex)
const concave = [
    {x: 0, y: 0},
    {x: 2, y: 0},
    {x: 1, y: 1},
    {x: 0, y: 2}
];
console.log("Concave quadrilateral (non-convex):", isConvex(concave));

// Test 5: Pentagon (convex)
const pentagon = [
    {x: 0, y: 0},
    {x: 1, y: 0},
    {x: 1.5, y: 0.5},
    {x: 0.5, y: 1.5},
    {x: 0, y: 0.5}
];
console.log("Pentagon (convex):", isConvex(pentagon));

// Test 6: Collinear points (should be non-convex)
const collinear = [
    {x: 0, y: 0},
    {x: 1, y: 1},
    {x: 2, y: 2}
];
console.log("Collinear points (non-convex):", isConvex(collinear));

// Test 7: Invalid input - not enough points
try {
    const invalid = [{x: 0, y: 0}, {x: 1, y: 1}];
    console.log("Invalid polygon (too few points):", isConvex(invalid));
} catch (e) {
    console.log("Invalid polygon (too few points) - caught error:", e.message);
}

console.log("\nTests completed.");

